/* 
  Preventing the Mass Assignment Vulnerability 
*/

// ❌ BAD: Blindly trusting all incoming data
app.put('/api/users/:id', async (req, res) => {
  // Hacker sends { isAdmin: true }
  await db.users.update(req.params.id, req.body);
  // 🚨 HACKER IS NOW AN ADMIN 🚨
});

// ✅ GOOD: Explicitly destructuring and picking ONLY allowed fields
app.put('/api/users/:id', async (req, res) => {
  // We ignore anything else they might have put in the body
  const { firstName, lastName, bio } = req.body;

  await db.users.update(req.params.id, { firstName, lastName, bio });
  // Hacker remains a normal user.
});
